// JUnit の assertEquals がやっていることを自作して体験する
// ここを変えてみよう:fee の「>= 5000」を「> 5000」に変えて
//   (わざとバグを入れて)再実行。どのテストが赤になる?
public class MiniTest {
    // テスト対象:5000円以上は送料無料、1〜4999円は500円、0以下は-1
    static int fee(int amount) {
        if (amount <= 0) {
            return -1;
        }
        return amount >= 5000 ? 0 : 500;
    }

    static int passed = 0;
    static int failed = 0;

    // JUnit の assertEquals(期待値, 実際の値) の超簡易版
    static void assertEquals(int expected, int actual,
                             String name) {
        if (expected == actual) {
            passed++;
            System.out.println("✔ " + name);
        } else {
            failed++;
            System.out.println("✘ " + name
                    + "  expected: <" + expected
                    + "> but was: <" + actual + ">");
        }
    }

    public static void main(String[] args) {
        // Arrange・Act・Assert を1行にまとめた形
        assertEquals(500, fee(4999), "4999円は送料500円");
        assertEquals(0, fee(5000), "5000円ちょうどで無料");
        assertEquals(-1, fee(0), "0円はエラー");

        String bar = (failed == 0) ? "緑のバー" : "赤のバー";
        System.out.println(passed + " 件成功 / "
                + failed + " 件失敗 → " + bar);
    }
}

// 境界値の表をまとめて流す(@ParameterizedTest + @CsvSource の気持ち)
// ここを変えてみよう:①fee の 30 を 31 に変えてバグを入れる
//   ②表から境界値(30, 31)の行を消すと、バグに気づける?
public class TableTest {
    // テスト対象:30分まで無料、超えたら30分ごと(切り上げ)に200円
    static int fee(int minutes) {
        if (minutes <= 30) {
            return 0;
        }
        return (minutes - 30 + 29) / 30 * 200;
    }

    public static void main(String[] args) {
        int[][] cases = {
            // {入力, 期待値}
            {0, 0},      // 最小値
            {30, 0},     // 境界:無料の最後
            {31, 200},   // 境界:有料の最初
            {60, 200},
            {61, 400},
        };
        int failed = 0;
        for (int[] c : cases) {
            int actual = fee(c[0]);
            boolean ok = actual == c[1];
            if (!ok) {
                failed++;
            }
            System.out.println((ok ? "✔ " : "✘ ")
                    + c[0] + "分 → " + actual
                    + "円(期待値 " + c[1] + "円)");
        }
        System.out.println(
                failed == 0 ? "全部緑!" : failed + " 件が赤");
    }
}

// テストしやすい設計:「今日」を外から渡す
// ここを変えてみよう:today や limit の日付を変える /
//   Clock の日時を "2026-11-01T00:00:00Z" にしてみる
import java.time.*;

public class ClockDemo {
    // テストしにくい版:結果が実行した日で変わる
    static boolean isExpiredNow(LocalDate limit) {
        return LocalDate.now().isAfter(limit);
    }

    // テストしやすい版:「今日」を引数で受け取る
    static boolean isExpired(LocalDate limit,
                             LocalDate today) {
        return today.isAfter(limit);
    }

    public static void main(String[] args) {
        LocalDate limit = LocalDate.of(2026, 10, 31);

        // 境界値:期限当日はまだ OK、翌日から期限切れ
        System.out.println("10/31 → " + isExpired(limit,
                LocalDate.of(2026, 10, 31)));   // false
        System.out.println("11/01 → " + isExpired(limit,
                LocalDate.of(2026, 11, 1)));    // true

        // Clock を固定すれば now() も毎回同じ日になる
        Clock fixed = Clock.fixed(
                Instant.parse("2026-10-31T00:00:00Z"),
                ZoneId.of("Asia/Tokyo"));
        System.out.println("固定した今日: "
                + LocalDate.now(fixed));

        // isExpiredNow(limit) の結果は実行した日によって変わる
    }
}

